pub(crate) fn sprite_bytes(id: &str, size: u32) -> Option<&'static [u8]> {
    match (id, size) {
        ("calculator", 88) => Some(&SPRITE_CALCULATOR_88),
        ("calculator", 64) => Some(&SPRITE_CALCULATOR_64),
        ("calculator", 56) => Some(&SPRITE_CALCULATOR_56),
        ("calculator", 48) => Some(&SPRITE_CALCULATOR_48),
        ("calculator", 40) => Some(&SPRITE_CALCULATOR_40),
        ("chat", 88) => Some(&SPRITE_CHAT_88),
        ("chat", 64) => Some(&SPRITE_CHAT_64),
        ("chat", 56) => Some(&SPRITE_CHAT_56),
        ("chat", 48) => Some(&SPRITE_CHAT_48),
        ("chat", 40) => Some(&SPRITE_CHAT_40),
        ("settings", 88) => Some(&SPRITE_SETTINGS_88),
        ("settings", 64) => Some(&SPRITE_SETTINGS_64),
        ("settings", 56) => Some(&SPRITE_SETTINGS_56),
        ("settings", 48) => Some(&SPRITE_SETTINGS_48),
        ("settings", 40) => Some(&SPRITE_SETTINGS_40),
        ("stash", 88) => Some(&SPRITE_STASH_88),
        ("stash", 64) => Some(&SPRITE_STASH_64),
        ("stash", 56) => Some(&SPRITE_STASH_56),
        ("stash", 48) => Some(&SPRITE_STASH_48),
        ("stash", 40) => Some(&SPRITE_STASH_40),
        _ => None,
    }
}
